select '[#ImportData#]this._key = ''' + @ticket + ''';[#ImportData#]this._authorize = ' + rtrim(@@sysDatabaseName.dbo.FastBusiness$System$GetAuthorize(@@admin, @@userID, '[#CONTROLLER#]', 'New')) + ';load$Grid(this);' as message
return





				select 'dispose$Grid(this);' as message
